            raise ValueError(f"coupon {coupon['code']} has expired")
        min_subtotal = Decimal(str(coupon.get("min_subtotal", "0")))
        if subtotal >= min_subtotal:
            rate += Decimal(str(coupon["rate"]))
    return rate

